CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE FUNCTION public.assign_blink_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN
IF lower(NEW.email) = 'otaviotoledo610@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING;
ELSE DELETE FROM public.user_roles WHERE user_id = NEW.id AND role = 'admin'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.assign_blink_admin() FROM PUBLIC;
CREATE TRIGGER blink_admin_identity AFTER INSERT OR UPDATE OF email, email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_blink_admin();
CREATE TABLE public.site_settings (id text PRIMARY KEY DEFAULT 'main', content jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT main_settings_only CHECK (id = 'main'));
GRANT SELECT ON public.site_settings TO anon, authenticated;
GRANT INSERT, UPDATE ON public.site_settings TO authenticated;
GRANT ALL ON public.site_settings TO service_role;
ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public site content" ON public.site_settings FOR SELECT TO anon, authenticated USING(id = 'main');
CREATE POLICY "Admin insert content" ON public.site_settings FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admin update content" ON public.site_settings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(), 'admin')) WITH CHECK(public.has_role(auth.uid(), 'admin'));
CREATE TRIGGER settings_touch BEFORE UPDATE ON public.site_settings FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE POLICY "Admin read profiles" ON public.profiles FOR SELECT TO authenticated USING(public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admin update profiles" ON public.profiles FOR UPDATE TO authenticated USING(public.has_role(auth.uid(), 'admin')) WITH CHECK(public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Site media read" ON storage.objects FOR SELECT TO anon, authenticated USING(bucket_id = 'site-media');
CREATE POLICY "Admin media insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id = 'site-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admin media update" ON storage.objects FOR UPDATE TO authenticated USING(bucket_id = 'site-media' AND public.has_role(auth.uid(), 'admin')) WITH CHECK(bucket_id = 'site-media' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admin media delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id = 'site-media' AND public.has_role(auth.uid(), 'admin'));